function RIPS_RANK_CURVE(points, d):
    scales <- [ d(points[i], points[j]) for i < j ]
    sort scales ascending
    breaks, counts <- [], []
    c <- 0
    for s in scales:
        c <- c + 1
        if breaks and breaks[-1] == s: counts[-1] <- c
        else: append s to breaks, append c to counts
    return (breaks, counts)

